package ru.mytv.launcher;
import android.app.*;
import android.content.*;
import android.content.pm.*;
import android.provider.Settings;
import java.util.*;
import org.json.*;
public class HomeOptions {
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("home",0);}
 static Set<String> hidden(Context c){return new HashSet<>(prefs(c).getStringSet("hidden",Collections.emptySet()));}
 static ArrayList<ResolveInfo> favorites(MainActivity a,boolean includeHidden){ArrayList<ResolveInfo> out=new ArrayList<>();Set<String> hide=hidden(a);for(ResolveInfo r:a.inventory)if(a.prefs.getBoolean(r.activityInfo.packageName,false)&&(includeHidden||!hide.contains(r.activityInfo.packageName)))out.add(r);Map<String,Integer> rank=new HashMap<>();try{JSONArray order=new JSONArray(prefs(a).getString("order","[]"));for(int i=0;i<order.length();i++)rank.put(order.getString(i),i);}catch(Exception ignored){}out.sort((x,y)->Integer.compare(rank.getOrDefault(x.activityInfo.packageName,Integer.MAX_VALUE),rank.getOrDefault(y.activityInfo.packageName,Integer.MAX_VALUE)));return out;}
 static void saveOrder(MainActivity a,List<ResolveInfo> list){JSONArray order=new JSONArray();for(ResolveInfo r:list)order.put(r.activityInfo.packageName);prefs(a).edit().putString("order",order.toString()).apply();}
 static ResolveInfo find(MainActivity a,String pkg){for(ResolveInfo r:a.inventory)if(r.activityInfo.packageName.equals(pkg))return r;return null;}
 static void refresh(MainActivity a,String pkg){a.focusAfterRender=pkg;a.render();}
 static void tile(MainActivity a,String pkg){ResolveInfo r=find(a,pkg);if(r==null)return;boolean fav=a.prefs.getBoolean(pkg,false);new AlertDialog.Builder(a).setTitle(r.loadLabel(a.getPackageManager())).setItems(new String[]{fav?"Убрать из избранного":"Добавить в избранное","Скрыть приложение"},(d,n)->{if(n==0){ArrayList<ResolveInfo> order=favorites(a,true);if(fav)order.removeIf(x->x.activityInfo.packageName.equals(pkg));else order.add(r);a.prefs.edit().putBoolean(pkg,!fav).apply();saveOrder(a,order);refresh(a,pkg);}else{Set<String> hide=hidden(a);hide.add(pkg);prefs(a).edit().putStringSet("hidden",hide).apply();refresh(a,null);}}).setNegativeButton("Закрыть",null).show();}
 static void show(MainActivity a){new AlertDialog.Builder(a).setTitle("Настройки «Мой ТВ»").setItems(new String[]{"Избранное","Скрытые приложения","Размер плиток","Число колонок","Настройки заставки","Экран запуска","Обновления","О приложении и диагностика","Настройки приставки"},(d,n)->{switch(n){case 0:orderMenu(a);break;case 1:hiddenMenu(a);break;case 2:number(a,"Размер плиток","scale",new int[]{80,100,120},new String[]{"Компактные","Обычные","Крупные"},100);break;case 3:number(a,"Число колонок","columns",new int[]{0,3,4,5,6},new String[]{"Автоматически","3","4","5","6"},0);break;case 4:SaverOptions.show(a);break;case 5:delay(a);break;case 6:a.updates.check(true);break;case 7:AppInfo.show(a);break;case 8:a.open(new Intent(Settings.ACTION_SETTINGS));break;}}).setNegativeButton("Закрыть",null).show();}
 static void orderMenu(MainActivity a){ArrayList<ResolveInfo> fav=favorites(a,true);if(fav.isEmpty()){a.message("Избранное пусто. Удерживай OK на плитке в общей сетке, чтобы добавить приложение.");return;}Set<String> hide=hidden(a);String[] names=new String[fav.size()];for(int i=0;i<names.length;i++){ResolveInfo r=fav.get(i);names[i]=r.loadLabel(a.getPackageManager())+(hide.contains(r.activityInfo.packageName)?" (скрыто)":"");}new AlertDialog.Builder(a).setTitle("Избранное — управление").setItems(names,(d,n)->tile(a,fav.get(n).activityInfo.packageName)).setNegativeButton("Закрыть",null).show();}
 static void hiddenMenu(MainActivity a){ArrayList<ResolveInfo> list=new ArrayList<>(a.inventory);Set<String> hide=hidden(a);String[] names=new String[list.size()];boolean[] selected=new boolean[list.size()];for(int i=0;i<list.size();i++){ResolveInfo r=list.get(i);names[i]=r.loadLabel(a.getPackageManager())+"\n"+r.activityInfo.packageName;selected[i]=hide.contains(r.activityInfo.packageName);}new AlertDialog.Builder(a).setTitle("Отмеченные приложения будут скрыты").setMultiChoiceItems(names,selected,(d,n,checked)->{String pkg=list.get(n).activityInfo.packageName;if(checked)hide.add(pkg);else hide.remove(pkg);}).setPositiveButton("Сохранить",(d,n)->{prefs(a).edit().putStringSet("hidden",new HashSet<>(hide)).apply();refresh(a,null);}).setNegativeButton("Отмена",null).show();}
 static void number(MainActivity a,String title,String key,int[] values,String[] names,int fallback){int current=prefs(a).getInt(key,fallback),selected=0;for(int i=0;i<values.length;i++)if(values[i]==current)selected=i;new AlertDialog.Builder(a).setTitle(title).setSingleChoiceItems(names,selected,(d,n)->{prefs(a).edit().putInt(key,values[n]).apply();d.dismiss();refresh(a,null);show(a);}).setNegativeButton("Назад",(d,n)->show(a)).show();}
 static void delay(MainActivity a){int[] values={0,5,10,15,20,30};String[] labels={"Выключен","5 секунд","10 секунд","15 секунд","20 секунд","30 секунд"};int current=StartupGate.prefs(a).getInt("seconds",15),selected=0;for(int i=0;i<values.length;i++)if(values[i]==current)selected=i;new AlertDialog.Builder(a).setTitle("Ожидание после перезагрузки").setSingleChoiceItems(labels,selected,(d,n)->{StartupGate.prefs(a).edit().putInt("seconds",values[n]).apply();d.dismiss();show(a);}).setNegativeButton("Назад",(d,n)->show(a)).show();}
}
